package io.github.diodeme.ji.host.web;

import io.github.diodeme.ji.agent.AgentRuntimeBuilder;
import io.github.diodeme.ji.agent.ToolDefinition;
import io.github.diodeme.ji.ai.ModelRef;
import io.github.diodeme.ji.ai.ModelStreamEvent;
import io.github.diodeme.ji.ai.Usage;
import io.github.diodeme.ji.host.LocalTokenService;
import io.github.diodeme.ji.host.MemoryHostStore;
import io.github.diodeme.ji.host.PermissionBroker;
import io.github.diodeme.ji.host.PromptApplicationService;
import io.github.diodeme.ji.host.SessionApplicationService;
import io.github.diodeme.ji.testkit.ScriptedModelProvider;
import java.security.SecureRandom;
import java.time.Clock;
import java.util.List;
import java.util.Map;
import java.util.concurrent.CountDownLatch;

/** Real Local Host process used only by the Stage 1 browser contract. */
public final class Stage1HostFixture {
    private Stage1HostFixture() {}

    public static void main(String[] args) throws InterruptedException, java.io.IOException {
        int port = Integer.parseInt(System.getProperty("ji.test.port", "4174"));
        var provider = new ScriptedModelProvider()
                .enqueue(List.of(new ScriptedModelProvider.Step.Text("Work"),
                        new ScriptedModelProvider.Step.Text("ing"),
                        new ScriptedModelProvider.Step.Tool("call-1", "echo", Map.of("value", "hello")),
                        new ScriptedModelProvider.Step.Complete(Usage.ZERO, ModelStreamEvent.StopReason.TOOL_USE)))
                .enqueue(List.of(new ScriptedModelProvider.Step.Text("Done"),
                        new ScriptedModelProvider.Step.Complete(Usage.ZERO, ModelStreamEvent.StopReason.STOP)));
        PermissionBroker permissions = new PermissionBroker(Clock.systemUTC());
        var hostStore = new MemoryHostStore();
        var runtime = new AgentRuntimeBuilder().provider(provider).sessionStore(hostStore)
                .permissionDecider(permissions)
                .tool(ToolDefinition.sync("echo", "Echo input", Map.of("type", "object"),
                        (arguments, cancellation) -> ToolDefinition.ToolResult.text("echoed " + arguments.get("value"))))
                .build();
        var sessions = new SessionApplicationService(runtime);
        var tokens = new LocalTokenService(new SecureRandom(), Clock.systemUTC());
        var server = new LocalHostServer(sessions, permissions,
                new PromptApplicationService(sessions, hostStore),
                new ModelRef("faux", "faux-1"), tokens, port);
        Runtime.getRuntime().addShutdownHook(Thread.ofPlatform().unstarted(() -> {
            server.close();
            sessions.close();
        }));
        System.out.println("STAGE1_HOST_READY http://127.0.0.1:" + port + "/?token=" + server.issueLaunchToken());
        new CountDownLatch(1).await();
    }
}

